import { Component, useState } from "react";
import "./css/Festval_serch_details.css";

/*
class Festval_serch_details extends Component{
  
  constructor(props){
  
    super(props);

    const month = Date();

    this.state = {
      area : '전국',
      area_selected : false,
      default_month : month + "월",
      month_selected : false
    };
  
  }// constructor close;

  render() {
    const {area, default_month} = this.state;
    
    return (
      <div className='search_box'>
        <div className='search_class'>           
          <button id='class_ground' onClick={()=>{this.setState({area_selected : true});}} className='select_box'>{area}</button>
          <button id='class_date' className='select_box'>{default_month}</button>                       
          <div id="select_hidden"></div>
        </div>          
        <div className='thema_class'>
          <div id="class_thema1" className='thema_box'>계절테마1</div>
          <div id="class_thema2" className='thema_box'>계절테마2</div>
          <div id="" className='thema_box'>계절테마3</div>
          <div id="class_thema4" className='thema_box'>계절테마4</div>
        </div>
      </div>        
    );

  }//render close


}// class close
*/

const Festval_serch_details = () => {

  let [area,setArea] = useState("전국",null);
  let [date,setDate] = useState("월별",null);

  const onClickSelected_area = () => onClickItem();
  const onClickSelected_date = () => onClickItem();
  
  const onClickItem = (e) =>{
    console.log(e);    
    console.log(e.target);   
    this.setArea("dddddd");
  }

  return(
    <div className='search_box'>
        <div className='search_class'>                     
          <button id='class_ground' onClick={onClickSelected_area} className='select_button'>{area}</button>
          <button id='class_date' onClick={onClickSelected_date} className='select_button'>{date}</button>                       
          <div id="select_hidden">
            <ul id="area_selete">
              <li className="select_item" onClick={onClickItem}>전국</li>
              <li className="select_item" onClick={onClickItem}>서울</li>
              <li className="select_item">인천</li>
              <li className="select_item">대전</li>
              <li className="select_item">대구</li>
              <li className="select_item">광주</li>
              <li className="select_item">부산</li>
            </ul>
          </div>  
        </div>          
        
        <div className='thema_class'>
          <div id="class_thema1" className='thema_box'>계절테마1</div>
          <div id="class_thema2" className='thema_box'>계절테마2</div>
          <div id="" className='thema_box'>계절테마3</div>
          <div id="class_thema4" className='thema_box'>계절테마4</div>
        </div>
      </div>
  );

};// Festval_search_detauls close



export default Festval_serch_details;
